const { MinPriorityQueue } = require("@datastructures-js/priority-queue");
const input = require("fs").readFileSync(0, "utf8");

function findKthLargest(nums, k) {
  const heap = new MinPriorityQueue(); // the k largest numbers so far, the smallest on top
  for (const num of nums) {
    heap.enqueue(num);
    if (heap.size() > k) {
      heap.dequeue();
    }
  }
  return heap.front();
}

const [n, k, ...nums] = input.trim().split(/\s+/).map(Number);
console.log(findKthLargest(nums.slice(0, n), k));

