#include <functional>
#include <iostream>
#include <queue>
#include <vector>

int findKthLargest(const std::vector<int>& nums, int k) {
    // The k largest numbers so far, the smallest on top.
    std::priority_queue<int, std::vector<int>, std::greater<int>> heap;
    for (int num : nums) {
        heap.push(num);
        if (static_cast<int>(heap.size()) > k) {
            heap.pop();
        }
    }
    return heap.top();
}

int main() {
    int n, k;
    std::cin >> n >> k;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    std::cout << findKthLargest(nums, k) << "\n";
    return 0;
}

